import {
  UIElement,
  PlayerController,
  playerContext,
  selectPlayback,
  type PropertyValues,
} from '@videojs/html';

class MediaCompleteContainerElement extends UIElement {
  static readonly tagName = 'media-complete-container';

  static override properties = {
    show_on_load: { type: Boolean },
  };

  show_on_load = false;

  #playback = new PlayerController(this, playerContext, selectPlayback);

  update(changed: PropertyValues) {
    super.update(changed);

    const playback = this.#playback.value;

    this.style.display = playback !== undefined && ((!playback.started && this.show_on_load) || playback.ended) ? 'block' : 'none';
  }
}

customElements.define(MediaCompleteContainerElement.tagName, MediaCompleteContainerElement);