import {
  UIElement,
  PlayerController,
  playerContext,
  selectPlayback,
  type PropertyValues,
} from '@videojs/html';

class MediaResumeContainerElement extends UIElement {
  static readonly tagName = 'media-resume-container';

  #playback = new PlayerController(this, playerContext, selectPlayback);

  update(changed: PropertyValues) {
    super.update(changed);

    this.style.display = this.#playback.value?.started ? 'none' : 'block';
  }
}

customElements.define(MediaResumeContainerElement.tagName, MediaResumeContainerElement);